CREATE TABLE IF NOT EXISTS `coa_dungeon_rescale_loot` (
    `map_id` SMALLINT UNSIGNED NOT NULL,
    `difficulty` TINYINT UNSIGNED NOT NULL,
    `source_item` INT UNSIGNED NOT NULL,
    `target_item` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`map_id`, `difficulty`, `source_item`)
) ENGINE=InnoDB;

DELETE FROM `coa_dungeon_rescale_loot` WHERE `map_id` IN (545, 546, 547);

UPDATE `creature` SET `spawnMask` = `spawnMask` | 4 WHERE `map` IN (545, 546, 547) AND (`spawnMask` & 2) <> 0 AND `id` <> 22421;
UPDATE `gameobject` SET `spawnMask` = `spawnMask` | 4 WHERE `map` IN (545, 546, 547) AND (`spawnMask` & 2) <> 0;
UPDATE `quest_template` SET `MinLevel` = 60 WHERE `ID` = 9724 AND `MinLevel` BETWEEN 61 AND 254;
UPDATE `quest_template` SET `MinLevel` = 60 WHERE `ID` = 9731 AND `MinLevel` BETWEEN 61 AND 254;
UPDATE `quest_template` SET `MinLevel` = 60 WHERE `ID` = 9732 AND `MinLevel` BETWEEN 61 AND 254;
UPDATE `quest_template_addon` SET `MaxLevel` = 60 WHERE `ID` IN (9714,9715,9717,9719,9724,9731,9732,9738,9763,9764,9765,9766,9876,10459,11368,11369,11370,11371) AND `MaxLevel` BETWEEN 1 AND 59;
